const body = $input.first()?.json?.body || $input.first()?.json || {};
const options = body.options || {};
const raw = options.rawValues || {};
const documents = Array.isArray(options.referenceDocuments)
  ? options.referenceDocuments
  : Array.isArray(body.referenceDocuments)
    ? body.referenceDocuments
    : [];
const notes = String(options.referenceNotes || body.referenceNotes || raw.referenceNotes || '').slice(0, 20000);
let remaining = 80000;
const referenceBlocks = documents.slice(0, 30).map((document, index) => {
  const name = String(document?.name || `Reference ${index + 1}`).slice(0, 160);
  const text = String(document?.text || '').trim().slice(0, Math.max(0, remaining));
  remaining -= text.length;
  return text ? `### SOURCE ${index + 1}: ${name}\n${text}` : '';
}).filter(Boolean);
if (notes) referenceBlocks.push(`### CLIENT KEYWORDS AND EXTRA RULES\n${notes}`);
const pages = (Array.isArray(body.batchItems) ? body.batchItems : [])
  .map((item, index) => ({
    page: Number(item?.page) || index + 1,
    pageType: String(item?.pageType || 'instruction'),
    text: String(item?.text || '').trim(),
    imageDescription: String(item?.imageDescription || '').trim(),
    imagePrompt: String(item?.imagePrompt || item?.prompt || item?.imageDescription || '').trim()
  }))
  .filter((item) => item.text || item.imagePrompt || item.imageDescription);
return [{ json: {
  body,
  bookTitle: String(body.storybookTitle || raw.storybookTitle || 'My Picture Book'),
  bookStyle: String(body.storybookStyle || raw.storybookStyle || options.imageStyle || 'Watercolor Picture Book'),
  grade: String(body.storybookGrade || raw.storybookGrade || 'Grade 2'),
  pages,
  referenceContext: referenceBlocks.join('\n\n') || 'No external reference material was provided.'
} }];

const source = $('整理参考资料').first()?.json || {};
const output = $input.first()?.json || {};
let rawText = output.text ?? output.output ?? output.response ?? output.content ?? output;
if (typeof rawText !== 'string') rawText = JSON.stringify(rawText);
rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let storyBible;
try {
  storyBible = JSON.parse(rawText);
} catch (error) {
  const match = rawText.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('The story-bible model did not return JSON');
  storyBible = JSON.parse(match[0]);
}
const pages = Array.isArray(source.pages) ? source.pages : [];
if (!Array.isArray(storyBible.pagePlans)) storyBible.pagePlans = [];
storyBible.pagePlans = pages.map((page, index) => {
  const planned = storyBible.pagePlans.find((item) => Number(item?.page) === page.page) || storyBible.pagePlans[index] || {};
  return {
    page: page.page,
    scene: String(page.imagePrompt || page.imageDescription || planned.scene || page.text),
    characters: Array.isArray(planned.characters) ? planned.characters : [],
    objects: Array.isArray(planned.objects) ? planned.objects : [],
    composition: String(planned.composition || '')
  };
});
return [{ json: { body: source.body || {}, storyBible } }];

const input = $input.first()?.json?.body || $input.first()?.json || {};
const options = input.options || {};
const raw = options.rawValues || {};
const sourcePages = Array.isArray(input.batchItems) ? input.batchItems : [];
const fallbackPages = String(raw.storybookContent || input.storybookContent || '')
  .split(/\r?\n+/)
  .map((text, index) => ({ page: index + 1, text: text.trim() }))
  .filter((item) => item.text);
const pages = (sourcePages.length ? sourcePages : fallbackPages).slice(0, 20);
if (pages.length < 2) throw new Error('A picture book needs at least 2 pages. Put one page on each line.');
const title = String(input.storybookTitle || raw.storybookTitle || 'My Picture Book').trim();
const style = String(input.storybookStyle || raw.storybookStyle || options.imageStyle || 'Watercolor Picture Book').trim();
const grade = String(input.storybookGrade || raw.storybookGrade || 'Grade 2 (7-8 years)').trim();
const width = Math.max(512, Math.min(2048, Number(input.width) || 1280));
const height = Math.max(512, Math.min(2048, Number(input.height) || 720));
const baseSeed = Math.floor(Math.random() * 900000000000000);
const comfyuiUrls = [
  'https://vcbj5meqyp1y7ifw-8188.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8189.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8190.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8191.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8192.container.x-gpu.com'
];
const negative = String(input.negative_prompt || 'blurry, low quality, watermark, logo, misspelled text, unreadable text, photorealistic, 3d, inconsistent character, extra limbs, cropped');
const workflowTemplate = {
  '1': { inputs: { unet_name: 'z_image_turbo_bf16.safetensors', weight_dtype: 'default' }, class_type: 'UNETLoader' },
  '2': { inputs: { vae_name: 'ae.safetensors' }, class_type: 'VAELoader' },
  '3': { inputs: { clip_name: 'qwen_3_4b.safetensors', type: 'lumina2', device: 'default' }, class_type: 'CLIPLoader' },
  '4': { inputs: { shift: 3, model: ['1', 0] }, class_type: 'ModelSamplingAuraFlow' },
  '5': { inputs: { width, height, batch_size: 1 }, class_type: 'EmptySD3LatentImage' },
  '6': { inputs: { text: '', clip: ['3', 0] }, class_type: 'CLIPTextEncode' },
  '7': { inputs: { text: negative, clip: ['3', 0] }, class_type: 'CLIPTextEncode' },
  '8': { inputs: { seed: baseSeed, steps: 15, cfg: 1.5, sampler_name: 'euler', scheduler: 'simple', denoise: 1, model: ['4', 0], positive: ['6', 0], negative: ['7', 0], latent_image: ['5', 0] }, class_type: 'KSampler' },
  '9': { inputs: { samples: ['8', 0], vae: ['2', 0] }, class_type: 'VAEDecode' },
  '10': { inputs: { filename_prefix: 'Storybook', images: ['9', 0] }, class_type: 'SaveImage' }
};
const stylePrompt = style.toLowerCase().includes('watercolor') || style.includes('水彩')
  ? 'Oliver Jeffers-inspired loose watercolor and black colored-pencil sketch, translucent low-saturation gray-blue, dusty pink, sage, ochre and lavender washes, warm off-white paper, playful imperfect hand-drawn linework'
  : style.toLowerCase().includes('paper') || style.includes('剪纸')
    ? 'layered handmade paper-cut collage, tactile paper fibers, soft child-friendly shapes, warm editorial storybook composition'
    : 'friendly premium children picture-book illustration, simple rounded shapes, warm soft colors and expressive hand-drawn details';
return pages.map((page, index) => {
  const pageNo = Number(page.page) || index + 1;
  const text = String(page.text || '').trim();
  const visualPrompt = String(page.imagePrompt || page.imageDescription || page.prompt || '').trim();
  const workflow = JSON.parse(JSON.stringify(workflowTemplate));
  const exactText = pageNo === 1 ? `${title}\n${text}` : text;
  workflow['6'].inputs.text = [
    `A polished landscape children's picture-book page, page ${pageNo} of ${pages.length}, for ${grade}.`,
    stylePrompt + '.',
    `PRIMARY PAGE-SPECIFIC VISUAL DESCRIPTION — follow literally: ${visualPrompt}.`,
    `Visible page text context only: ${text}.`,
    'Sparse free-floating composition with at least 50 percent calm negative space. Flat full-page artwork, subtle pencil marks and watercolor splashes, no mockup, no book photographed in a scene.',
    `Render only this exact English page text, clearly and legibly in a playful handwritten black font: "${exactText}".`,
    `Put a very small plain page number ${pageNo} at the bottom center. Do not add any other words.`
  ].join(' ');
  workflow['8'].inputs.seed = baseSeed + pageNo;
  workflow['10'].inputs.filename_prefix = `Storybook_${title.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 32)}_P${String(pageNo).padStart(2, '0')}`;
  return { json: {
    page: pageNo,
    title: `${title} · Page ${pageNo}`,
    pageText: text,
    pageType: String(page.pageType || 'instruction'),
    imageDescription: String(page.imageDescription || ''),
    imagePrompt: visualPrompt,
    comfyuiUrl: comfyuiUrls[index % comfyuiUrls.length],
    comfyuiPayload: { prompt: workflow }
  } };
});

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  if (!workflow?.['6']?.inputs || !workflow?.['7']?.inputs) {
    throw new Error(`Missing ComfyUI prompt graph for page ${data.page || '?'}`);
  }

  const singlePoppyRule = [
    'HIGHEST PRIORITY CHARACTER COUNT RULE:',
    'Show exactly ONE Poppy character in the entire image.',
    'Poppy appears once only, as one small full-body character in the lower-right area.',
    'Do not clone, repeat, mirror, duplicate, tile, crowd, or show another Poppy in the background.',
    'No second cloud mascot, no group of mascots, no Poppy-shaped decoration, and no reflection of Poppy.',
    'All other illustrated objects must be food, utensils, furniture, scenery, or abstract watercolor marks—not living cloud characters.'
  ].join(' ');

  workflow['6'].inputs.text = `${singlePoppyRule} ${workflow['6'].inputs.text}`;
  workflow['7'].inputs.text = [
    workflow['7'].inputs.text,
    'multiple Poppy characters',
    'two Poppies',
    'duplicate character',
    'cloned mascot',
    'repeated mascot',
    'character crowd',
    'group of cloud characters',
    'multiple pink clouds with faces',
    'mirrored character',
    'character reflection',
    'Poppy-shaped decoration'
  ].filter(Boolean).join(', ');

  return { json: data };
});

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  const positiveNode = workflow?.['6']?.inputs;
  const loraNode = workflow?.['11']?.inputs;
  if (!positiveNode || !loraNode) throw new Error(`Invalid character prompt for page ${data.page || '?'}`);

  const verboseRuleEnd = 'All other illustrated objects must be food, utensils, furniture, scenery, or abstract watercolor marks—not living cloud characters.';
  let scenePrompt = String(positiveNode.text || '');
  const ruleEndIndex = scenePrompt.indexOf(verboseRuleEnd);
  if (ruleEndIndex >= 0) scenePrompt = scenePrompt.slice(ruleEndIndex + verboseRuleEnd.length).trim();
  scenePrompt = scenePrompt.replace(/\bPoppy\b/g, 'the mascot');

  positiveNode.text = [
    'solo, single subject, exactly one character, character count: 1,',
    'poppy_character appears once as a small full-body mascot in the lower-right corner,',
    'all remaining elements are inanimate objects and scenery,',
    scenePrompt
  ].join(' ');

  // A slightly softer LoRA weight preserves identity while reducing cloning artifacts.
  loraNode.strength_model = 0.7;
  loraNode.strength_clip = 0.85;
  return { json: data };
});

const parsed = $('解析故事与角色圣经').first()?.json || {};
const bible = parsed.storyBible || {};
const protagonist = bible.protagonist || null;
const recurring = Array.isArray(bible.recurringCharacters) ? bible.recurringCharacters : [];
const visual = bible.visualBible || {};
const visualBibleText = [
  visual.medium ? `Medium: ${visual.medium}.` : '',
  visual.palette ? `Palette: ${visual.palette}.` : '',
  visual.paper ? `Paper/background: ${visual.paper}.` : '',
  visual.layout ? `Layout system: ${visual.layout}.` : '',
  visual.typography ? `Typography: ${visual.typography}.` : ''
].filter(Boolean).join(' ');
const recurringBibleText = [protagonist, ...recurring]
  .filter(Boolean)
  .map((character) => `${character.name}: ${character.visualIdentity}; role: ${character.role || 'recurring character'}.`)
  .join(' ');
const negativeRules = Array.isArray(visual.negativeRules) ? visual.negativeRules.join(', ') : '';

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  if (!workflow?.['6']?.inputs || !workflow?.['7']?.inputs) throw new Error(`Invalid page workflow ${data.page || '?'}`);
  const pagePlan = (Array.isArray(bible.pagePlans) ? bible.pagePlans : []).find((plan) => Number(plan?.page) === Number(data.page)) || {};
  const characterPlan = Array.isArray(pagePlan.characters) ? pagePlan.characters : [];
  const pageCharacterText = characterPlan.length
    ? characterPlan.map((character) => `${character.name}, count ${Number(character.count) || 1}, ${character.action || ''}, expression ${character.expression || 'natural'}`).join('; ')
    : 'No character unless the page scene explicitly requires one.';
  workflow['6'].inputs.text = [
    'GLOBAL STORY BIBLE — repeat immutable character traits exactly on every page:',
    recurringBibleText || 'No fixed protagonist was established.',
    visualBibleText,
    `PAGE ${data.page} PLAN: scene: ${pagePlan.scene || data.pageText || ''}. Characters: ${pageCharacterText}. Objects: ${(pagePlan.objects || []).join(', ')}. Composition: ${pagePlan.composition || ''}.`,
    workflow['6'].inputs.text
  ].filter(Boolean).join(' ');
  if (negativeRules) workflow['7'].inputs.text = `${workflow['7'].inputs.text}, ${negativeRules}`;
  data.characterPlan = characterPlan;
  data.storyBibleApplied = true;
  if (characterPlan.some((character) => /\bpoppy\b/i.test(String(character?.name || '')))) data.title = `${data.title || ''} · Poppy`;
  return { json: data };
});

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  const positiveNode = workflow?.['6']?.inputs;
  const negativeNode = workflow?.['7']?.inputs;
  const samplerNode = workflow?.['8']?.inputs;
  if (!positiveNode || !negativeNode || !samplerNode) {
    throw new Error(`Invalid ComfyUI prompt graph for page ${data.page || '?'}`);
  }

  const poppyBible = 'Poppy is always the same small pink cloud character: rounded scalloped cloud body, two solid black dot eyes without pupils, tiny curved smile, two thin black legs and oval black feet. Keep her proportions, face and colors identical on every page.';
  let positive = String(positiveNode.text || '').replace(poppyBible, '').replace(/\s+/g, ' ').trim();
  const characterContext = `${data.title || ''} ${data.pageText || ''}`;
  const usesPoppy = /\bpoppy(?:_character)?\b/i.test(characterContext);

  if (usesPoppy) {
    if (!workflow['11']) {
      workflow['11'] = { inputs: { lora_name: 'poppy.safetensors', strength_model: 0.7, strength_clip: 0.85, model: ['4', 0], clip: ['3', 0] }, class_type: 'LoraLoader' };
    }
    const loraNode = workflow['11'].inputs;
    positiveNode.clip = ['11', 1];
    negativeNode.clip = ['11', 1];
    samplerNode.model = ['11', 0];
    loraNode.strength_model = 0.7;
    loraNode.strength_clip = 0.85;
    positiveNode.text = [
      'poppy_character,',
      'Use Poppy only where required by this page’s story content; let the story determine her action, placement, and the number of other characters.',
      'Poppy is a small pink cloud mascot with a rounded scalloped body, two solid black dot eyes, a tiny curved smile, two thin black legs, and oval black feet.',
      positive
    ].join(' ');
    data.characterMode = 'poppy-lora';
  } else {
    // No named Poppy in this page or book title: remove the IP LoRA completely.
    // The base model now follows the page content and may draw no character,
    // one character, or several characters as the story requires.
    positiveNode.clip = ['3', 0];
    negativeNode.clip = ['3', 0];
    samplerNode.model = ['4', 0];
    delete workflow['11'];
    positiveNode.text = [
      'Follow the story content literally. Do not add Poppy or any branded cloud mascot unless explicitly named.',
      'Let the page text determine whether the scene has no characters, one character, or multiple characters.',
      positive
    ].join(' ');
    negativeNode.text = [negativeNode.text, 'unrequested mascot', 'unrequested pink cloud character', 'branded character'].filter(Boolean).join(', ');
    data.characterMode = 'content-only';
  }

  return { json: data };
});

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  const positiveNode = workflow?.['6']?.inputs;
  const negativeNode = workflow?.['7']?.inputs;
  if (!positiveNode || !negativeNode) throw new Error(`Invalid style workflow for page ${data.page || '?'}`);

  const unifiedStyle = [
    'UNIFIED GUIDED-BOOK STYLE — HIGHEST VISUAL PRIORITY:',
    'Oliver Jeffers-inspired loose translucent watercolor washes with expressive imperfect black pen-and-ink sketch lines, warm, restrained, playful, and emotionally gentle.',
    'Extremely low-saturation washed palette only: gray-blue, dusty gray-pink, sage gray-green, muted gray-orange, pale gray-yellow, and soft gray-purple.',
    'More than 80 percent calm negative space; only a few objects sparsely distributed with strong breathing room.',
    'Free non-grid composition with varied sizes and angles, casually scattered like an artist working journal; no rows and no rigid centering.',
    'Keep faint pencil construction lines, restrained watercolor splashes, and occasional hand-drawn tool icons.',
    'Flat light warm-beige textured drawing-paper background; no border, no frame, no open-book effect, no photographed book.',
    'Landscape composition. Use imperfect handwritten English only for the exact supplied page text. Never invent object labels.'
  ].join(' ');
  positiveNode.text = `${unifiedStyle} ${positiveNode.text || ''}`;
  negativeNode.text = [negativeNode.text, 'unrequested mascot', 'unrequested pink cloud character', 'branded cloud character', 'high saturation', 'neon colors', 'grid layout', 'rigid rows', 'catalog layout', 'heavy composition', 'busy background', 'border', 'frame', 'open book mockup', 'photographed book'].filter(Boolean).join(', ');
  data.characterMode = data.characterMode || 'content-only';
  return { json: data };
});

return $input.all().map((item) => {
  const data = item.json || {};
  const workflow = data.comfyuiPayload?.prompt;
  const positiveNode = workflow?.['6']?.inputs;
  const negativeNode = workflow?.['7']?.inputs;
  if (!positiveNode || !negativeNode) throw new Error(`Invalid typography prompt for page ${data.page || '?'}`);

  let positive = String(positiveNode.text || '');
  positive = positive.replace(/Put a very small plain page number \d+ at the bottom center\. Do not add any other words\./gi, '');
  positiveNode.text = [
    positive,
    'ABSOLUTE VISIBLE-TEXT LOCK: Render only the exact English page text already specified in this prompt.',
    'Do not render the image description, prompt instructions, page type, page number, labels, captions, annotations, legends, equations, pronunciation guides, speech bubbles, callouts, Chinese characters, non-English writing, pseudo-text, or any additional letters or words.',
    'All visual options must be communicated with pictures and layout only.'
  ].filter(Boolean).join(' ');
  negativeNode.text = [
    negativeNode.text,
    'Chinese characters',
    'Chinese text',
    'non-English text',
    'page number',
    'labels',
    'captions',
    'annotations',
    'speech bubbles',
    'callouts',
    'extra words',
    'extra letters',
    'pseudo-text',
    'gibberish typography',
    'misspelled text',
    'duplicated text'
  ].filter(Boolean).join(', ');
  return { json: data };
});

const responses = $input.all();
const prepared = $('准备绘本分页任务').all();
const assets = responses.map((item, index) => {
  const meta = prepared[index]?.json || {};
  const response = item.json || {};
  const executionId = response.prompt_id || response.id;
  if (!executionId) throw new Error(`ComfyUI did not return a task id for page ${meta.page || index + 1}`);
  return {
    executionId,
    comfyuiUrl: meta.comfyuiUrl,
    workflowType: 'image',
    status: 'submitted',
    page: meta.page || index + 1,
    title: meta.title || `Picture Book · Page ${index + 1}`,
    pageText: meta.pageText || ''
  };
});
assets.sort((a, b) => a.page - b.page);
return [{ json: { success: true, status: 'submitted', pageCount: assets.length, assets } }];
